contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint extraAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(extraAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balanceBeforeWithdraw = address(c).balance;

        bool revertFlag;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertFlag = true;
        } else {
            revertFlag = false;
        }

        uint balanceAfterWithdraw = address(c).balance;

        assert(
            balanceBeforeWithdraw < depositAmount
                ? (revertFlag && balanceAfterWithdraw == balanceBeforeWithdraw)
                : true
        );
    }

    receive() external payable {}
}

