pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, uint256 extraAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(extraAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint balanceBeforeWithdraw = address(c).balance;
        bool revertFlag;
        try c.withdrawAll() {
            revertFlag = false;
        } catch {
            revertFlag = true;
        }
        uint balanceAfterWithdraw = address(c).balance;
        assertTrue(balanceBeforeWithdraw < depositAmount
                ? (revertFlag && balanceAfterWithdraw == balanceBeforeWithdraw)
                : true);
    }

    function testFuzz_run(uint256 depositAmount, uint256 extraAmount) public {
        _run(depositAmount, extraAmount);
    }

    receive() external payable {}
}
